package org.example.items;

public enum ItemType implements TaxStrategy {
    RAW {
        @Override
        public double calculateTax(double price) {
            return 0.125 * price;
        }
    },
    MANUFACTURED {
        @Override
        public double calculateTax(double price) {
            double taxOnRaw = 0.125 * price;
            return taxOnRaw + 0.02 * (price + taxOnRaw);
        }
    },
    IMPORTED {
        @Override
        public double calculateTax(double price) {
            double importDuty = 0.10 * price;
            double costAfterDuty = price + importDuty;
            double surcharge;
            if (costAfterDuty <= 100) {
                surcharge = 5;
            } else if (costAfterDuty <= 200) {
                surcharge = 10;
            } else {
                surcharge = 0.05 * costAfterDuty;
            }
            return importDuty + surcharge;
        }
    };

    public static ItemType fromString(String type) {
        try {
            return valueOf(type.toUpperCase());
        } catch (IllegalArgumentException e) {
            throw new IllegalArgumentException("Invalid item type. Allowed: raw, manufactured, imported.");
        }
    }
}

