package org.example.items;

public class TaxCalculator {

    public static double calculateSalesTaxPerItem(Item item) {
        double price = item.getPrice();
        String type = item.getType();
        switch (type) {
            case "raw":
                return 0.125 * price;
            case "manufactured":
                double taxOnRaw = 0.125 * price;
                return taxOnRaw + 0.02 * (price + taxOnRaw);
            case "imported":
                double importDuty = 0.10 * price;
                double costAfterDuty = price + importDuty;
                double surcharge;
                if (costAfterDuty <= 100) {
                    surcharge = 5;
                } else if (costAfterDuty <= 200) {
                    surcharge = 10;
                } else {
                    surcharge = 0.05 * costAfterDuty;
                }
                return importDuty + surcharge;
            default:
                throw new IllegalArgumentException("Invalid item type: " + type);
        }
    }

        return item.getPrice() + calculateSalesTaxPerItem(item);
        return ItemType.fromString(item.getType()).calculateFinalPrice(item.getPrice());
    }
}

package org.example.items;

public class TaxCalculator {
    private static TaxStrategy getStrategy(String type) {
        return switch (type.toLowerCase()) {
            case "raw" -> new RawTaxStrategy();
            case "manufactured" -> new ManufacturedTaxStrategy();
            case "imported" -> new ImportedTaxStrategy();
            default -> throw new IllegalArgumentException("Invalid item type: " + type);
        };
    }

    public static double calculateSalesTaxPerItem(Item item) {
        TaxStrategy strategy = getStrategy(item.getType());
        return strategy.calculateTax(item.getPrice());
    }

    public static double calculateFinalPricePerItem(Item item) {
        TaxStrategy strategy = getStrategy(item.getType());
        return strategy.calculateFinalPrice(item.getPrice());
    }
}

package org.example.items;

public interface TaxStrategy {
    double calculateTax(double price);

    default double calculateFinalPrice(double price) {
        return price + calculateTax(price);
    }
}

package org.example.items;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class ImportedTaxStrategyTest {
    private final ImportedTaxStrategy strategy = new ImportedTaxStrategy();

    @Test
    void calculateTax_WhenPriceLessThan100_ShouldAddFlatSurchargeOf5() {
        // Given
        double price = 80.0;
        // 8 (10% import duty) + 5 (surcharge) = 13
        double expectedTax = 13.0;

        // When
        double actualTax = strategy.calculateTax(price);

        // Then
        assertEquals(expectedTax, actualTax, 0.001, "Import tax for items <= 100 should include 10% duty + 5 surcharge");
    }

    @Test
    void calculateTax_WhenPriceBetween100And200_ShouldAddFlatSurchargeOf10() {
        // Given
        double price = 150.0;
        // 15 (10% import duty) + 10 (surcharge) = 25
        double expectedTax = 25.0;

        // When
        double actualTax = strategy.calculateTax(price);

        // Then
        assertEquals(expectedTax, actualTax, 0.001, "Import tax for items between 100 and 200 should include 10% duty + 10 surcharge");
    }

    @Test
    void calculateTax_WhenPriceAbove200_ShouldAdd5PercentSurcharge() {
        // Given
        double price = 500.0;
        // 50 (10% import duty) + 27.5 (5% of 550) = 77.5
        double expectedTax = 77.5;

        // When
        double actualTax = strategy.calculateTax(price);

        // Then
        assertEquals(expectedTax, actualTax, 0.001, "Import tax for items > 200 should include 10% duty + 5% of (price + duty)");
    }

    @Test
    void calculateFinalPrice_ShouldIncludeAllTaxesAndSurcharges() {
        // Given
        double price = 500.0;
        // 500 + 77.5 = 577.5
        double expectedFinalPrice = 577.5;

        // When
        double actualFinalPrice = strategy.calculateFinalPrice(price);

        // Then
        assertEquals(expectedFinalPrice, actualFinalPrice, 0.001, "Final price should include import duty and surcharge");
    }
}

package org.example.items;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class ManufacturedTaxStrategyTest {
    private final ManufacturedTaxStrategy strategy = new ManufacturedTaxStrategy();

    @Test
    void calculateTax_ShouldIncludeBaseTaxAndManufacturingTax() {
        // Given
        double price = 100.0;
        // 12.5 (base tax) + 2.25 (2% of 112.5) = 14.75
        double expectedTax = 14.75;

        // When
        double actualTax = strategy.calculateTax(price);

        // Then
        assertEquals(expectedTax, actualTax, 0.001, "Manufactured item tax should include base tax and 2% of (price + base tax)");
    }

    @Test
    void calculateFinalPrice_ShouldIncludeAllTaxes() {
        // Given
        double price = 100.0;
        // 100 + 14.75 = 114.75
        double expectedFinalPrice = 114.75;

        // When
        double actualFinalPrice = strategy.calculateFinalPrice(price);

        // Then
        assertEquals(expectedFinalPrice, actualFinalPrice, 0.001, "Final price should include all taxes");
    }
}

package org.example.items;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class RawTaxStrategyTest {
    private final RawTaxStrategy strategy = new RawTaxStrategy();

    @Test
    void calculateTax_ShouldReturn12Point5Percent() {
        // Given
        double price = 100.0;
        double expectedTax = 12.5; // 12.5% of 100

        // When
        double actualTax = strategy.calculateTax(price);

        // Then
        assertEquals(expectedTax, actualTax, 0.001, "Raw item tax should be 12.5% of price");
    }

    @Test
    void calculateFinalPrice_ShouldIncludeTax() {
        // Given
        double price = 100.0;
        double expectedFinalPrice = 112.5; // price + 12.5% tax

        // When
        double actualFinalPrice = strategy.calculateFinalPrice(price);

        // Then
        assertEquals(expectedFinalPrice, actualFinalPrice, 0.001, "Final price should include 12.5% tax");
    }
}

package org.example.items;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class TaxCalculatorTest {

    @Test
    void calculateSalesTaxPerItem_ForRawItem() {
        // Given
        Item item = new Item("Raw Material", 100.0, 1, "raw");
        double expectedTax = 12.5; // 12.5% of 100

        // When
        double actualTax = TaxCalculator.calculateSalesTaxPerItem(item);

        // Then
        assertEquals(expectedTax, actualTax, 0.001, "Raw item tax calculation failed");
    }

    @Test
    void calculateSalesTaxPerItem_ForManufacturedItem() {
        // Given
        Item item = new Item("Manufactured Item", 100.0, 1, "manufactured");
        double expectedTax = 14.75; // 12.5 + 2% of 112.5

        // When
        double actualTax = TaxCalculator.calculateSalesTaxPerItem(item);

        // Then
        assertEquals(expectedTax, actualTax, 0.001, "Manufactured item tax calculation failed");
    }

    @Test
    void calculateSalesTaxPerItem_ForImportedItem() {
        // Given
        Item item = new Item("Imported Item", 500.0, 1, "imported");
        double expectedTax = 77.5; // 50 (10%) + 27.5 (5% of 550)

        // When
        double actualTax = TaxCalculator.calculateSalesTaxPerItem(item);

        // Then
        assertEquals(expectedTax, actualTax, 0.001, "Imported item tax calculation failed");
    }

    @Test
    void calculateFinalPricePerItem_ForAllTypes() {
        // Given
        Item rawItem = new Item("Raw Material", 100.0, 1, "raw");
        Item manufacturedItem = new Item("Manufactured Item", 100.0, 1, "manufactured");
        Item importedItem = new Item("Imported Item", 500.0, 1, "imported");

        // When & Then
        assertEquals(112.5, TaxCalculator.calculateFinalPricePerItem(rawItem), 0.001, 
            "Raw item final price calculation failed");
        assertEquals(114.75, TaxCalculator.calculateFinalPricePerItem(manufacturedItem), 0.001, 
            "Manufactured item final price calculation failed");
        assertEquals(577.5, TaxCalculator.calculateFinalPricePerItem(importedItem), 0.001, 
            "Imported item final price calculation failed");
    }

    @Test
    void calculateSalesTaxPerItem_ShouldThrowException_ForInvalidType() {
        // Given
        Item invalidItem = new Item("Invalid", 100.0, 1, "invalid");

        // When & Then
        assertThrows(IllegalArgumentException.class, 
            () -> TaxCalculator.calculateSalesTaxPerItem(invalidItem),
            "Should throw IllegalArgumentException for invalid item type");
    }
}
